const $=s=>document.querySelector(s);
const normalize=Kitchen.normalize;
const recipes=RECIPE_DATA.map(r=>({...r,ingredients:r.items.map(i=>i.id),amounts:r.items.map(i=>Kitchen.format(i.quantity,i.unit)+' '+Kitchen.label(i.id))}));
let ingredients=[],pantry={},hasSearched=false,visibleLimit=8;
let pantrySnapshot='',pantrySavedAt=null;
try{const saved=JSON.parse(localStorage.getItem('fridge-fork-pantry-v1'));if(saved?.items){for(const [id,stock] of Object.entries(saved.items).slice(0,100)){if(id.length<=80&&id!=='__proto__'&&stock&&Kitchen.units[stock.unit]&&(stock.quantity===null||(Number.isFinite(stock.quantity)&&stock.quantity>=0)))pantry[id]={quantity:stock.quantity,unit:stock.unit};}pantrySavedAt=saved.updatedAt;}}catch{}
function savePantry(){const snapshot=JSON.stringify(pantry);if(snapshot!==pantrySnapshot){try{if(pantrySnapshot)pantrySavedAt=new Date().toISOString();localStorage.setItem('fridge-fork-pantry-v1',JSON.stringify({items:pantry,updatedAt:pantrySavedAt}));pantrySnapshot=snapshot;$('#pantry-status').textContent=Object.keys(pantry).length?'Saved on this device'+(pantrySavedAt?' · '+new Date(pantrySavedAt).toLocaleDateString():''):'';}catch{$('#pantry-status').textContent='Fridge changes could not be saved on this device.';}}}

const staples=['oil','salt','pepper'];
const servingCount=()=>Number($('#servings').value)||2;
const cuisineUnits={all:'metric',Filipino:'metric',International:'metric'};
const system=()=>$('#units').value==='auto'?(cuisineUnits[$('#cuisine').value]||'metric'):$('#units').value;
function applyRegion(){const us=$('#region').value==='us';const select=$('#units');if(us&&!select.querySelector('option[value="us"]'))select.append(new Option('US (oz, tbsp)','us'));if(!us){if(select.value==='us')select.value='auto';select.querySelector('option[value="us"]')?.remove();}if(!us){for(const stock of Object.values(pantry)){if(['oz','lb'].includes(stock.unit)){if(stock.quantity!==null)stock.quantity=Kitchen.convert(stock.quantity,stock.unit,'g');stock.unit='g';}}}renderIngredients();updateFilterSummary();renderResults();}
try{$('#region').value=localStorage.getItem('fridge-fork-region')==='us'?'us':'other';}catch{}
$('#region').onchange=()=>{try{localStorage.setItem('fridge-fork-region',$('#region').value);}catch{}applyRegion();};
function updateFilterSummary(){const metric=system()==='metric';$('#filter-hint').textContent=(metric?'Metric':'US units')+' · '+$('#difficulty').selectedOptions[0].textContent+' · '+$('#diet').selectedOptions[0].textContent+' · '+$('#max-time').selectedOptions[0].textContent;$('#measurement-note').textContent=$('#units').value==='auto'?($('#cuisine').value==='Filipino'?'Filipino recipes use metric by default.':$('#cuisine').value==='International'?'International includes many countries; metric is the default.':'Metric measurements by default.')+' Change them in More options.':'Using '+(metric?'metric':'US')+' measurements. Choosing a cuisine resets to its default.';}
const amountText=(q,u)=>Kitchen.format(q,u,system());
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
function available(){return new Set(Object.keys(pantry).filter(k=>pantry[k].quantity===null||pantry[k].quantity>0));}
function checkRecipe(r){return Kitchen.assess(r.items,pantry,servingCount()/r.servings);}
function groceryNeeds(r){return checkRecipe(r).filter(i=>i.status==='missing'||i.status==='short');}
function formatRecipeAmount(r,index){const item=r.items[index];return amountText(item.quantity*servingCount()/r.servings,item.unit)+' '+Kitchen.label(item.id);}
function matchScore(r){const checks=checkRecipe(r);const meaningful=checks.filter(i=>!staples.includes(i.id));const matched=meaningful.filter(i=>pantry[i.id]&&(pantry[i.id].quantity===null||pantry[i.id].quantity>0)).length;return {...r,checks,matched,missing:checks.filter(i=>i.status==='missing'||i.status==='short').map(i=>i.id),status:Kitchen.status(checks),coverage:matched/meaningful.length};}
function ranked(){return recipes.map(matchScore).sort((a,b)=>({ready:0,quantities:1,needs:2}[a.status]-{ready:0,quantities:1,needs:2}[b.status])||b.coverage-a.coverage||a.missing.length-b.missing.length||b.matched-a.matched||a.time-b.time);}
const known=new Set(recipes.flatMap(r=>[...r.items,...r.optional].map(i=>i.id)));
known.forEach(id=>$('#ingredient-names').append(new Option(id,id)));
function defaultUnit(id){return recipes.flatMap(r=>[...r.items,...r.optional]).find(i=>i.id===id)?.unit||'g';}
function add(value){visibleLimit=8;const values=value.split(',').map(normalize).filter(Boolean);let skipped=false;for(const id of values){if(Object.keys(pantry).length>=100){skipped=true;break;}if(id.length>80){skipped=true;continue;}if(!Object.hasOwn(pantry,id)&&id!=='__proto__')pantry[id]={quantity:null,unit:defaultUnit(id)};}ingredients=Object.keys(pantry);hasSearched=ingredients.length>0;$('#ingredient').value='';$('#notice').textContent=skipped?'Limit: 100 ingredients, 80 characters per name.':'Add quantities below to check portions. Blank means quantity unknown.';renderIngredients();renderResults();}
function renderIngredients(){ingredients=Object.keys(pantry);$('#count').textContent=ingredients.length;const list=$('#chips');list.replaceChildren();for(const id of ingredients){const row=node('div','','pantry-row');const title=node('div','','pantry-name');title.append(node('span',Kitchen.label(id)));const remove=node('button','×');remove.setAttribute('aria-label','Remove '+id);remove.onclick=()=>{delete pantry[id];renderIngredients();renderResults();};title.append(remove);row.append(title);if(id.startsWith('unspecified ')){const select=node('select');select.setAttribute('aria-label','Specify '+id);const choices=id==='unspecified rice'?['cooked rice','uncooked rice']:['ground beef','ground pork','ground chicken'];select.append(new Option('Choose type…',''));choices.forEach(v=>select.append(new Option(Kitchen.label(v),v)));select.onchange=()=>{if(!select.value)return;const old=pantry[id];if(!pantry[select.value])pantry[select.value]={quantity:old.quantity,unit:defaultUnit(select.value)};delete pantry[id];renderIngredients();renderResults();};row.append(select);}else{const fields=node('div','','pantry-quantity');const input=node('input');input.type='number';input.min='0';input.max='100000';input.step='any';input.placeholder='Amount?';input.value=pantry[id].quantity??'';input.setAttribute('aria-label','Quantity of '+id);input.oninput=input.onchange=()=>{const q=input.value===''?null:Number(input.value);if(q!==null&&(!Number.isFinite(q)||q<0||q>100000)){input.value='';pantry[id].quantity=null;}else pantry[id].quantity=q;renderResults();};const unit=node('select');unit.setAttribute('aria-label','Unit for '+id);Object.keys(Kitchen.units).filter(u=>$('#region').value==='us'||!['oz','lb'].includes(u)).forEach(u=>unit.append(new Option(u,u)));unit.value=pantry[id].unit;unit.onchange=()=>{pantry[id].unit=unit.value;renderResults();};fields.append(input,unit);row.append(fields);if(!known.has(id))row.append(node('small','No exact match in this collection yet.'));}list.append(row);}
const quick=['eggs','cooked rice','broccoli','ground beef','ground pork','tomatoes','spinach','garlic','onion','oil','salt','soy sauce','potatoes','chayote','dry pasta','chicken thigh'];$('#quick').replaceChildren(...quick.filter(id=>!pantry[id]).map(id=>{const b=node('button','+ '+Kitchen.label(id));b.onclick=()=>add(id);return b;}));$('#staples').checked=staples.every(id=>pantry[id]);}
const stateText={ready:'Ready to cook',quantities:'Check quantities',needs:'Needs ingredients'};
function resultSummary(checks){const needs=checks.filter(i=>i.status==='missing'||i.status==='short');if(needs.length)return needs.map(i=>(i.status==='short'?'More ':'Missing ')+Kitchen.label(i.id)+' ('+amountText(i.shortage,i.unit)+')').join(' · ');const unknown=checks.filter(i=>i.status==='unknown');return unknown.length?'Check quantities or units: '+unknown.map(i=>Kitchen.label(i.id)).join(', '):'All required quantities are covered.';}
function meetsFilters(r){return Kitchen.matchesPreferences(r,{cuisine:$('#cuisine').value,difficulty:$('#difficulty').value,diet:$('#diet').value,maxTime:Number($('#max-time').value)});}
function renderResults(){savePantry();const active=Object.keys(pantry).length>0;let list=ranked().filter(meetsFilters);if(active)list=list.filter(r=>r.matched>0);if($('#ready').checked)list=list.filter(r=>r.status==='ready');$('#result-title').textContent=active?'Meals from what you have':($('#cuisine').value==='Filipino'?'Explore Filipino favourites':'Explore everyday recipes');$('#summary').textContent=`${list.length} recipes · ${servingCount()} servings`;$('#recipes').replaceChildren();if(!list.length)$('#recipes').append(node('div','No matches with these filters. Try another ingredient, confirm rice or meat types, or turn off “Ready to cook only”.','empty'));$('#show-more').hidden=list.length<=visibleLimit;$('#show-more').textContent='Show more recipes ('+Math.max(0,list.length-visibleLimit)+' remaining)';for(const r of list.slice(0,visibleLimit)){const card=node('article','','recipe-card');const body=node('div','','recipe-body');body.append(node('span',active?stateText[r.status]:r.cuisine,'badge '+(active&&r.status==='needs'?'missing':'')),node('span',`${r.time} min estimate · ${Kitchen.difficultyLabel(r.difficulty)}${active?' · '+r.cuisine:''}`,'time'),node('h3',r.name),node('p',active?resultSummary(r.checks):r.items.filter(i=>!staples.includes(i.id)).map(i=>Kitchen.label(i.id)).join(' · ')));const b=node('button','View recipe ↗','recipe-link');b.onclick=()=>openRecipe(r.id);body.append(b);card.append(body);$('#recipes').append(card);}renderPairs();}
const pairIds=[['sinangag','tomato-eggs'],['sinangag','paksiw-bangus'],['sinangag','bicol-express'],['fried-rice','broccoli-beef'],['fried-rice','broccoli-pork'],['fried-rice','broccoli-tofu'],['sinangag','chicken-adobo'],['sinangag','pork-adobo'],['sinangag','giniling'],['sinangag','tinola'],['vegetable-rice','lemon-chicken'],['sinangag','tofu-adobo'],['toast','lentil-soup'],['tomato-pasta','cucumber-salad']];
function renderPairs(){const target=$('#meal-pairs');target.replaceChildren();if(!ingredients.length)return;const pairs=pairIds.map(ids=>{const rs=ids.map(id=>recipes.find(r=>r.id===id));const combined=Kitchen.combine(rs,servingCount());const checks=Kitchen.assess(combined,pantry);return {rs,checks,state:Kitchen.status(checks),score:checks.filter(i=>!staples.includes(i.id)&&pantry[i.id]).length};}).filter(p=>p.rs.every(r=>meetsFilters(r)&&matchScore(r).matched>0)&&(!$('#ready').checked||p.state==='ready')).sort((a,b)=>({ready:0,quantities:1,needs:2}[a.state]-{ready:0,quantities:1,needs:2}[b.state])||b.score-a.score).slice(0,2);if(!pairs.length)return;target.append(node('h2','Make these together'),node('p','Each dish serves your selected portions. Shared ingredients are added together.','muted'));for(const p of pairs){const card=node('article','','pair-card');card.append(node('span',stateText[p.state],'badge'),node('h3',p.rs.map(r=>r.name).join(' + ')),node('p',resultSummary(p.checks)));p.rs.forEach(r=>{const b=node('button',r.name,'notebook-button');b.onclick=()=>openRecipe(r.id);card.append(b);});const plan=node('button','Add meal to shopping list','notebook-button');plan.onclick=()=>document.dispatchEvent(new CustomEvent('plan-recipes',{detail:p.rs.map(r=>r.id)}));card.append(plan);target.append(card);}}
const safetyUrl='https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures';
function safetyNotes(r){const ids=r.ingredients,notes=[];if(ids.some(i=>i.startsWith('chicken')))notes.push('Use a food thermometer: chicken must reach 74°C / 165°F.');if(ids.some(i=>i==='ground beef'||i==='ground pork'))notes.push('Use a food thermometer: minced beef or pork must reach 71°C / 160°F. Color alone is not a reliable check.');if(ids.some(i=>['pork shoulder','pork belly','beef ribs','oxtail'].includes(i)))notes.push('Whole-cut beef or pork must reach at least 63°C / 145°F followed by a 3-minute rest; continue cooking until tender.');if(ids.includes('milkfish'))notes.push('Fish must reach 63°C / 145°F; check carefully for bones.');if(ids.includes('eggs'))notes.push('Cook egg dishes to 71°C / 160°F; cook individual eggs until whites and yolks are firm.');if(ids.includes('cooked rice'))notes.push('Use rice chilled promptly, ideally within one hour, refrigerated and used within 24 hours. Reheat only once, until steaming hot throughout; leftovers should reach 74°C / 165°F.');return notes;}
function openRecipe(id){const r=recipes.find(r=>r.id===id);if(!r)return;const root=$('#recipe-detail');root.replaceChildren();root.dataset.recipeId=id;root.append(node('span',`${r.cuisine} · ${Kitchen.difficultyLabel(r.difficulty)} · ${r.time} min estimate · ${servingCount()} servings`,'badge'),node('h2',r.name),node('p',(r.provenance.license?'Open-license adaptation':'Original app draft')+' · Not kitchen-tested. Quantities and timing need cooking validation.','draft-note'),node('p',r.difficultyReason,'muted'),node('h3','Required ingredients'));const ul=node('ul');checkRecipe(r).forEach(i=>ul.append(node('li',amountText(i.required,i.unit)+' '+Kitchen.label(i.id)+' — '+({missing:'missing',short:'need '+amountText(i.shortage,i.unit)+' more',unknown:'quantity not checked',enough:'enough available'}[i.status]),i.status==='enough'?'have':'need')));root.append(ul);if(r.optional.length){root.append(node('h3','Optional extras'));const extras=node('ul');r.optional.forEach(i=>extras.append(node('li',amountText(i.quantity*servingCount()/r.servings,i.unit)+' '+Kitchen.label(i.id))));root.append(extras,node('p','Optional garlic: mince and briefly cook in the oil before the main ingredients. Bay leaf: simmer in the sauce and remove before serving. Spring onion or pepper: add at the end. Optional extras are excluded from readiness and grocery calculations.','muted'));}root.append(node('h3','Method'));const ol=node('ol');r.steps.forEach(s=>ol.append(node('li',s)));if(r.notes)root.append(node('p',r.notes,'draft-note'));root.append(ol,node('p','Steps describe the base 2-serving batch. Scale the ingredient list above; use a larger pan or cook in batches. Cooking time and water needs may change.','muted'));const notes=safetyNotes(r);if(notes.length){root.append(node('h3','Cooking and storage'));notes.forEach(s=>root.append(node('p',s)));const a=node('a','FoodSafety.gov temperature guidance');a.href=safetyUrl;a.target='_blank';a.rel='noopener';root.append(a);if(r.ingredients.includes('cooked rice')){const a=node('a',' · Food Standards Agency rice guidance');a.href='https://www.food.gov.uk/sites/default/files/media/document/sfbb-chinese-05-cooking-04-rice_0.pdf';a.target='_blank';a.rel='noopener';root.append(a);}}if(['cucumber-salad','chickpea-salad'].includes(r.id)){root.append(node('h3','Possible substitution'),node('p','Lime juice can replace lemon juice in the same volume; the flavor will differ. This is a suggestion only and does not count as available lemon juice.'));}const details=node('details');details.append(node('summary','Recipe origin & testing'));details.append(node('p',r.provenance.author+' · '+r.provenance.created),node('p',r.provenance.origin),node('p','Kitchen test: pending. No recipe photos are used.'),node('a','Sourcing policy'));details.querySelector('a').href='sourcing-policy.html';if(r.provenance.sourceUrl){const p=r.provenance;details.append(node('p',p.changes),node('p',p.rights));for(const [label,url] of [['Source recipe',p.sourceUrl],['Source revision',p.revisionUrl],['Contributors and history',p.historyUrl],[p.license,p.licenseUrl]]){const link=node('a',label);link.href=url;link.target='_blank';link.rel='noopener';const line=node('p');line.append(link);details.append(line);}}root.append(details);const report=node('details');report.append(node('summary','Help improve this recipe'));report.append(node('p','Share cooking results or an unmatched ingredient combination voluntarily. Nothing is sent automatically.'));const a=node('a','Report a recipe issue on GitHub');a.href='https://github.com/julianyoww/Fridge-Fork/issues/new?title='+encodeURIComponent('Recipe feedback: '+r.name)+'&body='+encodeURIComponent('Recipe ID: '+r.id+'\nServings cooked:\nWhat worked or needs correction:\nDo not include personal or medical information.');a.target='_blank';a.rel='noopener';report.append(a);root.append(report);$('#recipe-dialog').showModal();}
$('#add-form').onsubmit=e=>{e.preventDefault();add($('#ingredient').value);};$('#show-more').onclick=()=>{visibleLimit+=8;renderResults();};$('#find').onclick=()=>{hasSearched=true;renderResults();$('#result-title').scrollIntoView({block:'start'});};$('#clear').onclick=()=>{if(Object.keys(pantry).length&&!confirm('Clear all fridge ingredients saved on this device?'))return;pantry={};ingredients=[];hasSearched=false;$('#ready').checked=false;$('#notice').textContent='';renderIngredients();renderResults();};$('#staples').onchange=()=>{if($('#staples').checked)staples.forEach(id=>{if(!pantry[id])pantry[id]={quantity:null,unit:defaultUnit(id)};});else staples.forEach(id=>delete pantry[id]);renderIngredients();renderResults();};$('#ready').onchange=()=>renderResults();['servings','units','diet','max-time','difficulty'].forEach(id=>$('#'+id).onchange=()=>{visibleLimit=8;updateFilterSummary();renderResults();});$('#cuisine').onchange=()=>{visibleLimit=8;$('#units').value='auto';updateFilterSummary();renderResults();};applyRegion();$('#close-dialog').onclick=()=>$('#recipe-dialog').close();$('#example').onclick=()=>add('eggs, tomatoes, cooked rice');renderIngredients();renderResults();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_fridge_ingredients',description:'Replace fridge ingredients. Entries start with unknown quantities; rice and generic minced meat require type clarification.',inputSchema:{type:'object',properties:{ingredients:{type:'array',maxItems:100,items:{type:'string',minLength:1,maxLength:80}}},required:['ingredients'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Array.isArray(input.ingredients)||input.ingredients.length>100||input.ingredients.some(i=>typeof i!=='string'||!i.trim()||i.length>80))throw Error('Provide up to 100 ingredient names.');pantry={};add(input.ingredients.join(','));return {ingredients,recipes:ranked().filter(r=>r.matched>0).map(r=>({name:r.name,status:r.status,missing:r.missing}))};}})).catch(()=>{});}catch{}}
